var n=`0544-mashuai`;var a=`world-0544`;var o=`OM`;var t=`western-asia`;var r=4;var s=116;var u={en:`Mashuai`,ua:`Машуай`};var d={en:`A traditional dish from Oman, centered on sea bass, lemon juice, garlic, basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Оман. Основні складники: сібас, лимонний сік, часник, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 50 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 50 хвилин.`,t:[`marinating`],m:50,i:[[`sea-bass`,900,`g`],[`lemon-juice`,65,`ml`],[`ground-cumin`,5,`g`],[`garlic`,5,`clove`]]},{en:`Roast in a preheated 190°C oven for about 36 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 36 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:36,i:[[`sunflower-oil`,55,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 27 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 27 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:27,i:[[`basmati-rice`,400,`g`],[`ground-cardamom`,3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,25,`g`]]}];var g={slug:n,id:a,country:`OM`,region:t,servings:4,minutes:116,title:u,text:d,steps:l};export{o as country,g as default,a as id,s as minutes,t as region,r as servings,n as slug,l as steps,d as text,u as title};